div.script:
document.addEventListener('DOMContentLoaded', function() {
    const countrySelect = document.getElementById('country_id');
    const stateSelect = document.getElementById('state_id');

    // Store all state options with their country data-attribute
    const allStateOptions = Array.from(stateSelect.querySelectorAll('option[data-country]'));

    // Configuration handlers (Seats and Cycle)
    function updateConfig(seats, cycle) {
        // Disable interactions and show loading state
        document.getElementById('seat-input').style.opacity = '0.5';

        fetch('/subscriptions/checkout/update_config', {
            method: 'POST',
            headers: {'Content-Type': 'application/json'},
            body: JSON.stringify({
                params: {
                    plan_id: parseInt(''),
                    seats: seats,
                    cycle: cycle
                }
            })
        }).then(res => res.json()).then(data => {
            if(data.result && data.result.success) {
                if (data.result.redirect) {
                    window.location.href = data.result.redirect;
                } else {
                    window.location.reload();
                }
            } else if (data.result && data.result.error) {
                alert(data.result.error);
                document.getElementById('seat-input').style.opacity = '1';
            }
        }).catch(() => {
            document.getElementById('seat-input').style.opacity = '1';
        });
    }

    document.getElementById('seat-minus')?.addEventListener('click', () => {
        let val = parseInt(document.getElementById('seat-input').value);
        if(val > 1) updateConfig(val - 1, null);
    });

    document.getElementById('seat-plus')?.addEventListener('click', () => {
        let val = parseInt(document.getElementById('seat-input').value);
        updateConfig(val + 1, null);
    });

    document.getElementById('cycle-monthly')?.addEventListener('click', () => {
        if ('' !== 'monthly') updateConfig(null, 'monthly');
    });

    document.getElementById('cycle-yearly')?.addEventListener('click', () => {
        if ('' !== 'yearly') updateConfig(null, 'yearly');
    });

    function filterStates(countryId, selectedStateId) {
        // Remove all existing state options except the placeholder
        Array.from(stateSelect.options).forEach(opt => {
            if (opt.value !== '') stateSelect.removeChild(opt);
        });

        const matching = allStateOptions.filter(opt => 
            !countryId || opt.dataset.country == countryId
        );

        if (matching.length === 0) {
            stateSelect.style.display = 'none';
            stateSelect.closest('.col-md-6').style.display = 'none';
        } else {
            stateSelect.style.display = '';
            stateSelect.closest('.col-md-6').style.display = '';
            matching.forEach(opt => {
                const clone = opt.cloneNode(true);
                if (selectedStateId && clone.value == selectedStateId) {
                    clone.selected = true;
                }
                stateSelect.appendChild(clone);
            });
        }
    }

    // Initial filter on page load
    const initialCountry = countrySelect ? countrySelect.value : '';
    const initialState = stateSelect ? stateSelect.querySelector('option[selected]') : null;
    filterStates(initialCountry, initialState ? initialState.value : null);

    // Filter when country changes
    if (countrySelect) {
        countrySelect.addEventListener('change', function() {
            filterStates(this.value, null);
        });
    }

    // Auto-save address on input (debounced)
    let timeout = null;
    const inputs = document.querySelectorAll('#name, #email, #street, #city, #zip, #country_id, #state_id');

    inputs.forEach(input => {
        input.addEventListener('input', function() {
            clearTimeout(timeout);
            timeout = setTimeout(() => {
                const data = {
                    name: document.getElementById('name') ? document.getElementById('name').value : '',
                    email: document.getElementById('email') ? document.getElementById('email').value : '',
                    street: document.getElementById('street') ? document.getElementById('street').value : '',
                    city: document.getElementById('city') ? document.getElementById('city').value : '',
                    zip_code: document.getElementById('zip') ? document.getElementById('zip').value : '',
                    country_id: document.getElementById('country_id') ? document.getElementById('country_id').value : '',
                    state_id: document.getElementById('state_id') ? document.getElementById('state_id').value : '',
                };
                fetch('/subscriptions/checkout/save_address', {
                    method: 'POST',
                    headers: {'Content-Type': 'application/json'},
                    body: JSON.stringify({params: data})
                });
            }, 500);
        });
    });
});
